97	    private static final class InMemorySessionStoreWithHeadersMarker
98	        extends WrappedStateStore<SessionStore<Bytes, byte[]>, Bytes, byte[]>
99	        implements SessionStore<Bytes, byte[]>, HeadersBytesStore {
100	        private InMemorySessionStoreWithHeadersMarker(final SessionStore<Bytes, byte[]> wrapped) {
101	            super(wrapped);
102	            if (wrapped.persistent()) {
103	                throw new IllegalArgumentException("Provided store must not be a persistent store, but it is.");
104	            }
105	        }
106	
107	        @Override
108	        public void remove(final Windowed<Bytes> sessionKey) {
109	            wrapped().remove(sessionKey);
110	        }
111	
112	        @Override
113	        public void put(final Windowed<Bytes> sessionKey, final byte[] aggregate) {
114	            wrapped().put(sessionKey, aggregate);
115	        }
116	
117	        @Override
118	        public KeyValueIterator<Windowed<Bytes>, byte[]> fetch(final Bytes key) {
119	            return wrapped().fetch(key);
120	        }
121	
122	        @Override
123	        public KeyValueIterator<Windowed<Bytes>, byte[]> fetch(final Bytes keyFrom, final Bytes keyTo) {
124	            return wrapped().fetch(keyFrom, keyTo);
125	        }
126	
127	        @Override
128	        public KeyValueIterator<Windowed<Bytes>, byte[]> findSessions(final Bytes key,
129	                                                                      final long earliestSessionEndTime,
130	                                                                      final long latestSessionStartTime) {
131	            return wrapped().findSessions(key, earliestSessionEndTime, latestSessionStartTime);
132	        }
133	
134	        @Override
135	        public KeyValueIterator<Windowed<Bytes>, byte[]> backwardFindSessions(final Bytes key,
136	                                                                              final long earliestSessionEndTime,
137	                                                                              final long latestSessionStartTime) {
138	            return wrapped().backwardFindSessions(key, earliestSessionEndTime, latestSessionStartTime);
139	        }
140	
141	        @Override
142	        public KeyValueIterator<Windowed<Bytes>, byte[]> findSessions(final Bytes keyFrom,
143	                                                                      final Bytes keyTo,
144	                                                                      final long earliestSessionEndTime,
145	                                                                      final long latestSessionStartTime) {
146	            return wrapped().findSessions(keyFrom, keyTo, earliestSessionEndTime, latestSessionStartTime);
147	        }
148	
149	        @Override
