/**
 * A {@link SessionBytesStoreSupplier} for time-ordered session stores that also supports headers.
 *
 * <p>This supplier is the header-aware counterpart of
 * {@link RocksDbTimeOrderedSessionBytesStoreSupplier}. By additionally implementing
 * {@link HeadersBytesStoreSupplier} it signals to the DSL materialization layer that a
 * header-capable store hierarchy should be built.
 */
public class RocksDbTimeOrderedSessionHeadersBytesStoreSupplier
    implements SessionBytesStoreSupplier, HeadersBytesStoreSupplier {

    private final String name;
    private final long retentionPeriod;
    private final boolean withIndex;

    public RocksDbTimeOrderedSessionHeadersBytesStoreSupplier(final String name,
                                                              final long retentionPeriod,
                                                              final boolean withIndex) {
        this.name = name;
        this.retentionPeriod = retentionPeriod;
        this.withIndex = withIndex;
    }

    @Override
    public String name() {
        return name;
    }

    @Override
    public SessionStore<Bytes, byte[]> get() {
        final RocksDBTimeOrderedSessionSegmentedBytesStoreWithHeaders bytesStore =
            new RocksDBTimeOrderedSessionSegmentedBytesStoreWithHeaders(
                name,
                metricsScope(),
                retentionPeriod,
                segmentIntervalMs(),
                withIndex
            );
        return new RocksDBTimeOrderedSessionStore(bytesStore);
    }

    @Override
    public String metricsScope() {
        return "rocksdb-session";
    }

    @Override
    public long segmentIntervalMs() {
        // Selected somewhat arbitrarily. Profiling may reveal a different value is preferable.
        return Math.max(retentionPeriod / 2, 60_000L);
    }

    @Override
    public long retentionPeriod() {
        return retentionPeriod;
    }
}
